'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var isAlmostSameValueFloat64Array = require( '@stdlib/assert/is-almost-same-value-float64array' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var dlasv2 = require( './../lib/dlasv2.js' );


// FIXTURES //

// NOTE: Expected outputs in fixtures were generated using the reference LAPACK Fortran implementation of DLASV2.
var INC_ORD_ELE = require( './fixtures/increasing_order_elements.json' );
var DEC_ORD_ELE = require( './fixtures/decreasing_order_elements.json' );
var LARGE_G = require( './fixtures/large_g_diagonal.json' );
var LARGE_G_AND_H_GT_1 = require( './fixtures/large_g_and_h_gt_1.json' );
var SMALL_G_AND_F_EQ_H = require( './fixtures/small_g_and_f_eq_h.json' );
var DIA_MAT = require( './fixtures/diagonal_matrix.json' );
var G_GT_F_AND_H = require( './fixtures/g_gt_f_and_h.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dlasv2, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 4', function test( t ) {
	t.strictEqual( dlasv2.length, 4, 'returns expected value' );
	t.end();
});

tape( 'the function computes the singular value decomposition of a triangular matrix with elements in increasing order', function test( t ) {
	var expected;
	var data;
	var out;

	data = INC_ORD_ELE;

	out = new Float64Array( 6 );

	dlasv2( data.F, data.G, data.H, out );
	expected = new Float64Array( data.out );
	t.strictEqual( isAlmostSameValueFloat64Array( out, expected, 1 ), true, 'returns expected value' );
	t.end();
});

tape( 'the function computes the singular value decomposition of a triangular matrix with elements in decreasing order', function test( t ) {
	var expected;
	var data;
	var out;

	data = DEC_ORD_ELE;

	out = new Float64Array( 6 );

	dlasv2( data.F, data.G, data.H, out );
	expected = new Float64Array( data.out );
	t.strictEqual( isAlmostSameValueFloat64Array( out, expected, 1 ), true, 'returns expected value' );
	t.end();
});

tape( 'the function computes the singular value decomposition of a triangular matrix with parameter `G` greater than `F` and `H`', function test( t ) {
	var expected;
	var data;
	var out;

	data = G_GT_F_AND_H;

	out = new Float64Array( 6 );

	dlasv2( data.F, data.G, data.H, out );
	expected = new Float64Array( data.out );
	t.strictEqual( isAlmostSameValueFloat64Array( out, expected, 1 ), true, 'returns expected value' );
	t.end();
});

tape( 'the function computes the singular value decomposition of a diagonal matrix', function test( t ) {
	var expected;
	var data;
	var out;

	data = DIA_MAT;

	out = new Float64Array( 6 );

	dlasv2( data.F, data.G, data.H, out );
	expected = new Float64Array( data.out );
	t.strictEqual( isAlmostSameValueFloat64Array( out, expected, 1 ), true, 'returns expected value' );
	t.end();
});

tape( 'the function computes the singular value decomposition of a diagonal matrix with a very large `G`', function test( t ) {
	var expected;
	var data;
	var out;

	data = LARGE_G;

	out = new Float64Array( 6 );

	dlasv2( data.F, data.G, data.H, out );
	expected = new Float64Array( data.out );
	t.strictEqual( isAlmostSameValueFloat64Array( out, expected, 1 ), true, 'returns expected value' );
	t.end();
});

tape( 'the function computes the singular value decomposition of a diagonal matrix with a very large `G` when `H` is greater than 1', function test( t ) {
	var expected;
	var data;
	var out;

	data = LARGE_G_AND_H_GT_1;

	out = new Float64Array( 6 );

	dlasv2( data.F, data.G, data.H, out );
	expected = new Float64Array( data.out );
	t.strictEqual( isAlmostSameValueFloat64Array( out, expected, 1 ), true, 'returns expected value' );
	t.end();
});

tape( 'the function computes the singular value decomposition of a diagonal matrix with an infinite `F`', function test( t ) {
	var expected;
	var out;

	expected = new Float64Array( [ 1.0, PINF, 0.0, 1.0, 0.0, 1.0 ] );
	out = new Float64Array( 6 );
	out = dlasv2( PINF, 2.0, 1.0, out );
	t.strictEqual( isAlmostSameValueFloat64Array( out, expected, 1 ), true, 'returns expected value' );
	t.end();
});

tape( 'the function computes the singular value decomposition of a diagonal matrix with tiny off-diagonal entries when `F` and `H` are equal', function test( t ) {
	var expected;
	var data;
	var out;

	data = SMALL_G_AND_F_EQ_H;

	out = new Float64Array( 6 );

	dlasv2( data.F, data.G, data.H, out );
	expected = new Float64Array( data.out );
	t.strictEqual( isAlmostSameValueFloat64Array( out, expected, 1 ), true, 'returns expected value' );
	t.end();
});
